    const member = useMemo(() => {
        if (!userId) return null;
        if (localMember) return localMember;
        const result = new RoomMember(null, userId);
        if (profile?.userId === userId) {
            result.name = profile.displayname;
            result.rawDisplayName = profile.displayname;
            result.events.member = {
                getContent: () => ({ avatar_url: profile.avatar_url }),
                getDirectionalContent: function () {
                    return this.getContent();
                },
            } as MatrixEvent;
        }
        return result;
    }, [userId, localMember, profile]);

    if (effectiveType === PillType.AtRoomMention) {
        return {
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId: room?.roomId || null,
            type: PillType.AtRoomMention,
        };
    }

    if (effectiveType === PillType.UserMention && member) {
        return {
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            text: member.rawDisplayName || userId,
            onClick: (e: ButtonEvent) => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
            resourceId: userId,
            type: PillType.UserMention,
        };
    }

    if (effectiveType === PillType.RoomMention && resourceId && /^[#!]/.test(resourceId)) {
        const client = MatrixClientPeg.get();
        const resolvedRoom =
            resourceId[0] === "#"
                ? client
                      .getRooms()
                      .find((r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId))
                : client.getRoom(resourceId);
        return {
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            text: resolvedRoom?.name || resourceId,
            onClick: null,
            resourceId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
        };
    }

    return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
}

export { PillType } from "../../../hooks/usePermalink";

export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

export function pillRoomNotifLen(): number {
    return "@room".length;
}

export interface PillProps {
    type?: PillType;
    url?: string;
    inMessage?: boolean;
    room?: Room;
    shouldShowPillAvatar?: boolean;
}

export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    const [hover, setHover] = useState(false);
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ type, url, room });
    if (!resolvedType || !text) return null;

    const classes = classNames("mx_Pill", {
        mx_UserPill: resolvedType === PillType.UserMention,
        mx_UserPill_me: resolvedType === PillType.UserMention && resourceId === MatrixClientPeg.get().getUserId(),
        mx_RoomPill: resolvedType === PillType.RoomMention,
        mx_SpacePill: resolvedType === "space",
        mx_AtRoomPill: resolvedType === PillType.AtRoomMention,
    });
    const content = (
        <>
            {shouldShowPillAvatar && avatar}
            <span className="mx_Pill_linkText">{text}</span>
            {hover && resourceId && <Tooltip label={resourceId} alignment={Alignment.Right} />}
        </>
    );
    const events = { onMouseOver: () => setHover(true), onMouseLeave: () => setHover(false) };

    return (
        <bdi>
            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
                {inMessage && url ? (
                    <a
                        className={classes}
                        href={url}
                        onClick={resolvedType === PillType.UserMention ? onClick : undefined}
                        {...events}
                    >
                        {content}
                    </a>
                ) : (
                    <span className={classes} {...events}>
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
}
